// Q2 from 50 to 199 and Q1 below 50 ("n/a" while their scaled is "n/a").
  protected bracketOf(p: Person): string | null {
    if (p.scaled === null) return null;
    return p.scaled >= 800 ? 'Q4' : p.scaled >= 200 ? 'Q3' : p.scaled >= 50 ? 'Q2' : 'Q1';
  }

